                    // Inline wrappers (for example a font span) have no usable
                    // clientWidth. Constrain to the actual block content box.
                    let parent = drag.image.parentElement;
                    while (parent !== this.editor && (getComputedStyle(parent).display === 'inline' || !parent.clientWidth)) parent = parent.parentElement;
                    const style = getComputedStyle(parent);
                    const available = parent.clientWidth - (parseFloat(style.paddingLeft) || 0) - (parseFloat(style.paddingRight) || 0);
                    const width = Math.max(24, Math.min(available || drag.width / drag.scale, (drag.width + delta) / drag.scale));
                    drag.image.style.width = width + 'px';
